default.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

$mismatchCount = 0
$workDirectory = Join-Path ([System.IO.Path]::GetTempPath()) ([System.Guid]::NewGuid().ToString())
try {
    New-Item -ItemType Directory -Path $workDirectory | Out-Null
    $exportPath = Join-Path $workDirectory 'export.inf'
    secedit /export /cfg $exportPath /areas SECURITYPOLICY | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'secedit /export failed' }
    $exported = @{}
    $section = ''
    foreach ($line in Get-Content -LiteralPath $exportPath) {
        if ($line -match '^\[(.+)\]\s*$') { $section = $Matches[1] }
        elseif ($line -match '^\s*([^=]+?)\s*=\s*(.*?)\s*$') { $exported[$section + '|' + $Matches[1]] = $Matches[2] }
    }
    $current = $exported['System Access|LockoutBadCount']
    if ($current -ne [string]$ODV_bad_login_lockout_count) {
        Write-Output 'Mismatch: [System Access] LockoutBadCount'
        $mismatchCount++
    }
}
finally {
    Remove-Item -LiteralPath $workDirectory -Recurse -Force -ErrorAction SilentlyContinue
}
if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

$workDirectory = Join-Path ([System.IO.Path]::GetTempPath()) ([System.Guid]::NewGuid().ToString())
try {
    New-Item -ItemType Directory -Path $workDirectory | Out-Null
    $infLines = @(
        '[Unicode]',
        'Unicode=yes',
        '[System Access]',
        ('LockoutBadCount = ' + $ODV_bad_login_lockout_count),
        '[Version]',
        'signature="$CHICAGO$"',
        'Revision=1'
    )
    $infPath = Join-Path $workDirectory 'policy.inf'
    Set-Content -LiteralPath $infPath -Value $infLines -Encoding Unicode
    secedit /configure /db (Join-Path $workDirectory 'policy.sdb') /cfg $infPath /areas SECURITYPOLICY | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'secedit /configure failed' }
}
finally {
    Remove-Item -LiteralPath $workDirectory -Recurse -Force -ErrorAction SilentlyContinue
}
exit 0
